"""Structure props generated by rule from a material of the biome: named gen:<material>:<shape>, painted by the painter of that material."""
import types
import zlib

import numpy as np

from drawing import shift, stepped_noise
from painters import PAINTERS, register, shared_of

SHAPES = {}
PREFIX = "gen:"


def columns_mask(heights, unit):
    """Mask of a row of columns given in units, each standing on the bottom edge."""
    tall = max(heights)
    mask = np.zeros((tall * unit, len(heights) * unit), bool)
    for position, height in enumerate(heights):
        if height > 0:
            mask[(tall - height) * unit:, position * unit:(position + 1) * unit] = True
    return mask


@register(SHAPES, "pile")
def shape_pile(rng, unit):
    """Heap of blocks, higher in the middle."""
    heights = [1, 2, int(rng.integers(2, 4)), 2, 1]
    lowered = int(rng.integers(0, 5))
    heights[lowered] = max(heights[lowered] - 1, 1)
    return columns_mask(heights, unit)


@register(SHAPES, "wall")
def shape_wall(rng, unit):
    """Piece of wall whose top edge is chipped and falls away on one side."""
    heights = [4, 4 - int(rng.integers(0, 2)), 4, 3 - int(rng.integers(0, 2)), 2, 1]
    return columns_mask(heights if rng.random() < 0.5 else heights[::-1], unit)


@register(SHAPES, "steps")
def shape_steps(rng, unit):
    """Three steps, each two units deep."""
    heights = [1, 1, 2, 2, 3, 3]
    return columns_mask(heights if rng.random() < 0.5 else heights[::-1], unit)


@register(SHAPES, "slab")
def shape_slab(rng, unit):
    """Low slab lying on the ground."""
    return columns_mask([1] * int(rng.integers(4, 7)), unit)


@register(SHAPES, "pillar")
def shape_pillar(rng, unit):
    """Whole pillar: a base, a shaft and a cap."""
    mask = np.zeros((6 * unit, 4 * unit), bool)
    mask[unit:5 * unit, unit:3 * unit] = True
    mask[:unit] = True
    mask[5 * unit:] = True
    return mask


@register(SHAPES, "pillar_broken")
def shape_pillar_broken(rng, unit):
    """Pillar broken above its base, its top stepped."""
    mask = np.zeros((4 * unit, 4 * unit), bool)
    mask[3 * unit:] = True
    mask[unit:3 * unit, unit:3 * unit] = True
    mask[:unit, unit:2 * unit] = True
    return mask if rng.random() < 0.5 else mask[:, ::-1]


@register(SHAPES, "drum")
def shape_drum(rng, unit):
    """Drum of a pillar fallen on its side."""
    return columns_mask([2, 2, 2], unit)


@register(SHAPES, "lintel")
def shape_lintel(rng, unit):
    """Lintel resting on one stub, its free end on the ground."""
    heights = [2, 2, 2, 2, 2, 1]
    mask = columns_mask(heights, unit)
    mask[unit:, unit:4 * unit] = False
    return mask if rng.random() < 0.5 else mask[:, ::-1]


def fray(mask, rng):
    """Natural outline for a material that is not laid on a grid: the top and the sides move in by a pixel or two, thin spurs removed."""
    out = mask.copy()
    rows, columns = mask.shape
    top = stepped_noise(columns, rng, (3, 7), [0, 0, 0, 1, 1, 2])
    left, right = stepped_noise(rows, rng, (3, 7), [0, 0, 1, 1]), stepped_noise(rows, rng, (3, 7), [0, 0, 1, 1])
    for x in range(columns):
        filled = np.where(mask[:, x])[0]
        if len(filled):
            out[filled[0]:filled[0] + top[x], x] = False
    for y in range(rows - 2):
        filled = np.where(out[y])[0]
        if len(filled):
            out[y, filled[0]:filled[0] + left[y]] = False
            out[y, filled[-1] + 1 - right[y]:filled[-1] + 1] = False
    core = out & shift(out, 0, 1, False) & shift(out, 0, -1, False) & shift(out, 1, 0, False) & shift(out, -1, 0, True)
    return core | shift(core, 0, 1, False) | shift(core, 0, -1, False) | shift(core, 1, 0, False) | shift(core, -1, 0, False)


def generate(biome, name):
    """Index sprite of a generated prop, drawn again the same way each time its name is asked for."""
    material, shape = name[len(PREFIX):].split("#")[0].split(":")
    declared = biome.materials[material]
    rng = np.random.default_rng(zlib.crc32(name.encode()))
    options = {key: value for key, value in declared["paint"].items() if key != "frame"}
    unit = options.get("cell", (8, 8))[1] if declared["aligned"] else 8
    mask = SHAPES[shape](rng, unit)
    if not declared["aligned"]:
        mask = fray(mask, rng)
    solid = np.zeros((mask.shape[0] + unit, mask.shape[1] + 2 * unit), bool)
    solid[unit:, unit:unit + mask.shape[1]] = mask
    canvas = np.zeros(solid.shape, np.uint8)
    PAINTERS[declared["painter"]](types.SimpleNamespace(biome=biome, rng=rng), canvas, solid, dict(shared_of(solid), shade_depth=False), options)
    canvas[~solid] = 0
    rows, columns = np.where(canvas > 0)
    return canvas[rows.min():, columns.min():columns.max() + 1]


class SpriteStore(dict):
    """Sprites of a biome by name; a name that starts with gen: is generated the first time it is asked for."""

    def __init__(self, biome, sprites):
        """Starts from the sprites read from disk."""
        super().__init__(sprites)
        self.biome = biome

    def __missing__(self, name):
        """Generates and keeps a prop asked for by its generated name."""
        if not name.startswith(PREFIX):
            raise KeyError(f"the biome {self.biome.name} has no sprite named {name}")
        self[name] = generate(self.biome, name)
        return self[name]
